async page => {
  const origin='http://127.0.0.1:8199',key='bhive-proto-flights-rpg-1';
  const out='/Users/bap/.codex/visualizations/2026/10/30/01a18d1b-9132-7852-9bfe-a736af52265f/bhive-flights-rpg-1/verification/';
  const browser=page.context().browser(),ctx=await browser.newContext({viewport:{width:1440,height:1100},serviceWorkers:'block'});
  const errors=[],remote=[],results=[];
  await ctx.route('**/*',r=>{if(r.request().url().startsWith(origin+'/'))return r.continue();remote.push(r.request().url());return r.abort();});
  const p=await ctx.newPage();p.on('pageerror',e=>errors.push(String(e)));p.on('console',m=>{if(m.type()==='error')errors.push(m.text());});
  const check=(value,label)=>{if(!value)throw new Error('FAIL: '+label);results.push(label);};
  const read=()=>p.evaluate(key=>JSON.parse(localStorage.getItem(key)),key);
  const ready=()=>p.locator('#homecoming-form').waitFor();
  const waitRecords=n=>p.waitForFunction(({key,n})=>JSON.parse(localStorage.getItem(key))?.records.length===n,{key,n});
  const equip=async(tool)=>{
    await p.locator('#character-card [data-action=character]').click();
    await p.locator('#character-form input[name=tool][value='+tool+']').check();
    await p.locator('#character-form button[type=submit]').click();await p.locator('#character-dialog').waitFor({state:'hidden'});
  };
  const choose=async(kind,route)=>{
    if(await p.locator('[data-action=return]').count())await p.locator('[data-action=return]').click();
    await p.locator('[data-action=choose]').click();await p.locator('[data-kind='+kind+']').click();
    await p.locator('[data-route='+route+']').click();
  };
  const send=async()=>{await p.locator('#send-form button[type=submit]').click();await p.locator('[data-action=arrive]').waitFor();};
  const arrive=async()=>{await p.locator('[data-action=arrive]').click();await ready();};
  const complete=async(outcome,n,note='')=>{await p.locator('input[name=outcome][value='+outcome+']').check();await p.locator('#homecoming-note').fill(note);await p.locator('#homecoming-form button[type=submit]').click();await waitRecords(n);};
  await p.goto(origin);await p.locator('[data-action=choose]').waitFor();
  await p.locator('#character-card [data-action=character]').click();
  await p.locator('#bee-name').fill('Fern');await p.locator('input[name=tool][value=cloak]').check();
  await p.screenshot({path:out+'character-desktop.png',fullPage:true});
  await p.locator('#character-form button[type=submit]').click();await p.locator('#character-dialog').waitFor({state:'hidden'});
  await p.reload();await p.locator('[data-action=choose]').waitFor();
  check((await read()).profile.name==='Fern'&&(await read()).profile.tool==='cloak','Character name and equipped gear persist after reload');
  await choose('rest','pause');
  await p.locator('#intention').fill('Set my phone aside.');await p.locator('#gentle').check();
  check(await p.locator('.objective').innerText().then(t=>t.includes('Set one thing down')),'Cloak changes the quest to its gentler objective');
  await p.screenshot({path:out+'quest-desktop.png',fullPage:true});
  await send();check((await read()).active.quest.gentle===true,'Gentler route is stored with the active quest');
  check(await p.evaluate(()=>document.getAnimations().some(a=>a.playState==='running')),'Equipped Forager has an animated send-off');
  await p.reload();await ready();
  await p.locator('#character-card [data-action=character]').click();
  check(await p.locator('.gear-choices').evaluate(e=>e.disabled&&[...e.querySelectorAll('input')].every(input=>input.matches(':disabled'))),'Equipment choices are disabled during a quest');
  await p.locator('[data-action=close-character]').click();
  await p.locator('input[value=partly]').check();await p.locator('#homecoming-note').fill('A short quiet moment.');
  await p.locator('#homecoming-form').evaluate(form=>{form.requestSubmit();form.requestSubmit();});await waitRecords(1);
  check((await read()).records.length===1,'Repeated homecoming submission creates only one cell');
  await p.locator('[data-action=teach]').click();await p.locator('#technique-title').fill('Put one thing down');
  await p.locator('#learn-form').evaluate(form=>{form.requestSubmit();form.requestSubmit();});
  await p.waitForFunction(key=>JSON.parse(localStorage.getItem(key)).techniques.length===1,key);
  check((await read()).techniques.length===1,'Repeated teaching creates one field-guide entry');
  await p.reload();await p.locator('[data-reuse]').waitFor();
  check(await p.locator('[data-reuse]').innerText().then(t=>t.includes('Put one thing down')),'Learned approach appears in the field guide after reload');
  await p.locator('[data-reuse]').click();await p.locator('#send-form').waitFor();
  check(await p.locator('#intention').inputValue()==='Set my phone aside.'&&await p.locator('#gentle').isChecked(),'Reusing an approach restores the plan, equipment and gentler route');
  check((await read()).records.length===1&&(await read()).active===null,'Preparing a reused approach does not mint a reward');
  await p.locator('#plain').check();await p.waitForFunction(key=>JSON.parse(localStorage.getItem(key)).plain,key);
  await send();await arrive();await complete('not_this_time',2,'Today went differently.');
  check(await p.locator('.record-hero').innerText().then(t=>t.includes('Not this time')),'Not this time has a completed record and full cell');
  check(await p.evaluate(()=>document.getAnimations().filter(a=>a.playState==='running').length===0),'Plain mode keeps RPG interactions instant');
  await equip('satchel');await choose('gather','prepare');
  await p.locator('#intention').fill('Have water ready for later.');await p.locator('#packed-step').fill('Put the bottle on the counter.');
  await p.locator('#panel [data-action=character]').click();await p.locator('input[name=tool][value=lantern]').check();
  await p.locator('#character-form button[type=submit]').click();await p.locator('#character-dialog').waitFor({state:'hidden'});
  check(await p.locator('#intention').inputValue()==='Have water ready for later.','Changing gear preserves the typed personal plan');
  await equip('satchel');
  check(await p.locator('#packed-step').inputValue()==='Put the bottle on the counter.','Returning to the Satchel preserves its packed-step draft');
  await send();await arrive();
  check(await p.locator('.packed-step').innerText().then(t=>t.includes('Put the bottle on the counter.')),'Satchel carries the first step into homecoming');
  await complete('done',3,'Made it easier to remember.');
  check((await read()).records[2].quest.pack==='Put the bottle on the counter.','Packed first step remains in the saved quest record');
  await equip('lantern');await choose('look','surroundings');await send();await arrive();
  await p.locator('#observation').fill('The window seat felt easier. <a clue>');
  await complete('plans_changed',4,'Changed where I sat.');
  check((await read()).records[3].observation==='The window seat felt easier. <a clue>','Lantern observation persists exactly and displays as text');
  await p.screenshot({path:out+'rpg-comb-desktop.png',fullPage:true});
  await p.setViewportSize({width:390,height:844});
  await p.screenshot({path:out+'rpg-comb-phone.png',fullPage:true});
  check(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'390px RPG layout has no horizontal overflow');
  await p.locator('#character-card [data-action=character]').click();
  await p.screenshot({path:out+'character-phone.png',fullPage:true});
  check(await p.locator('#character-dialog').evaluate(e=>e.scrollWidth<=e.clientWidth),'Character sheet fits the phone width');
  await p.locator('[data-action=close-character]').click();
  await p.setViewportSize({width:320,height:568});
  check(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'320px RPG layout has no horizontal overflow');
  await p.screenshot({path:out+'rpg-small-phone.png',fullPage:true});
  // Remaining quest branches are selected through the actual route cards.
  for(const [kind,route,n] of [['rest','lighten',5],['gather','outside',6],['look','energy',7]]){await choose(kind,route);await send();await arrive();await complete('done',n);}
  check((await read()).records.length===7,'Both approaches of all three quests work through the UI');
  const id=(await read()).records[0].id;
  await p.evaluate(async id=>{const {createStore}=await import('/model.mjs');const store=createStore(localStorage);await Promise.all(Array.from({length:20},()=>store.complete(id,'done','duplicate')));},id);
  check((await read()).records.length===7&&(await read()).records[0].outcome==='partly','Twenty repeated completion calls preserve the original RPG record');
  await p.evaluate(()=>{localStorage.setItem('bhive-proto-flights-0','original sentinel');localStorage.setItem('unrelated-save','untouched');});
  await p.locator('#reset').click();await p.locator('#confirm-reset').click();await p.locator('#reset-dialog').waitFor({state:'hidden'});
  check(await p.evaluate(key=>localStorage.getItem(key)===null&&localStorage.getItem('bhive-proto-flights-0')==='original sentinel'&&localStorage.getItem('unrelated-save')==='untouched',key),'RPG Reset removes only the RPG save');
  await p.reload();await p.locator('[data-action=choose]').waitFor();
  check((await read()).profile.name==='Pip'&&(await read()).techniques.length===0,'Reset restores the starter character and empty field guide');
  await p.emulateMedia({reducedMotion:'reduce'});await choose('rest','pause');await send();
  check(await p.evaluate(()=>document.getAnimations().filter(a=>a.playState==='running').length===0),'Reduced-motion preference applies to equipped quest send-off');
  check(remote.length===0,'No external network requests attempted');check(errors.length===0,'No browser errors');
  await ctx.close();return {passed:results.length,results,errors,remote,browser:browser.version()};
}
